{"content": "1|//! CUDA runtime: context management, device enumeration, compute capability detection.
2|//!
3|//! Wraps cuda-oxide's `CudaContext` to provide a stable interface for the inference
4|//! engine's GPU path. Handles initialization, device discovery, and error propagation.
5|
6|use cuda_core::{CudaContext, IntoResult};
7|use std::sync::Arc;
8|use tracing::{debug, warn};
9|
10|// Re-export cuda_bindings through cuda_core
11|use cuda_core::sys as cuda_sys;
12|
13|/// Error type for CUDA runtime operations.
14|#[derive(Debug, thiserror::Error)]
15|pub enum CudaError {
16|    #[error("CUDA driver not initialized: {0}")]
17|    NotInitialized(String),
18|
19|    #[error("CUDA device unavailable: ordinal={ordinal}")]
20|    DeviceUnavailable { ordinal: usize },
21|
22|    #[error("CUDA context creation failed: {0}")]
23|    ContextCreation(String),
24|
25|    #[error("CUDA compute capability unsupported: sm_{major}.{minor} < sm_100")]
26|    ComputeCapabilityUnsupported { major: i32, minor: i32 },
27|
28|    #[error("CUDA library load failed: {0}")]
29|    LibraryLoad(String),
30|
31|    #[error("CUDA error: {0}")]
32|    DriverError(String),
33|
34|    #[error("CUDA not available on this system")]
35|    NotAvailable,
36|}
37|
38|/// Information about a single CUDA device.
39|#[derive(Debug, Clone)]
40|pub struct CudaDeviceInfo {
41|    /// Zero-based device ordinal.
42|    pub ordinal: usize,
43|    /// Device name (e.g., "NVIDIA GeForce RTX 5060 Ti").
44|    pub name: String,
45|    /// Compute capability (major, minor).
46|    pub compute_capability: (i32, i32),
47|    /// Total device memory in bytes.
48|    pub total_memory: u64,
49|    /// Free device memory in bytes.
50|    pub free_memory: u64,
51|}
52|
53|impl CudaDeviceInfo {
54|    /// Whether this device can hold a model of the given size.
55|    pub fn can_hold_model(&self, model_bytes: u64) -> bool {
56|        // Reserve 2 GiB for overhead (KV cache, intermediate buffers, PTX JIT)
57|        self.free_memory > model_bytes + 2 * 1024 * 1024 * 1024
58|    }
59|
60|    /// Whether this device supports tcgen05 (sm_100+).
61|    pub fn supports_tcgen05(&self) -> bool {
62|        let (major, _minor) = self.compute_capability;
63|        major >= 10
64|    }
65|
66|    /// Whether this device supports WGMMA (sm_120+).
67|    pub fn supports_wgmma(&self) -> bool {
68|        let (major, _minor) = self.compute_capability;
69|        major >= 12
70|    }
71|}
72|
73|/// A live CUDA context for a specific device.
74|///
75|/// Wraps `Arc<CudaContext>` and tracks the device ordinal for routing.
76|#[derive(Debug, Clone)]
77|pub struct CudaRuntime {
78|    /// The underlying cuda-oxide context.
79|    ctx: Arc<CudaContext>,
80|    /// Device ordinal.
81|    ordinal: usize,
82|    /// Device info (cached at creation).
83|    device_info: CudaDeviceInfo,
84|}
85|
86|impl CudaRuntime {
87|    /// Create a new CUDA runtime for the device at `ordinal`.
88|    ///
89|    /// Initializes the CUDA driver, obtains the primary context, and queries
90|    /// device properties. Returns `CudaError::NotAvailable` if the device
91|    /// cannot be found or the driver fails to initialize.
92|    pub fn new(ordinal: usize) -> Result<Self, CudaError> {
93|        // Initialize CUDA driver
94|        unsafe {
95|            cuda_core::init(0).map_err(|e| CudaError::NotInitialized(e.to_string()))?;
96|        };
97|
98|        // Get device handle
99|        let cu_device = unsafe {
100|            let mut device = std::mem::MaybeUninit::uninit();
101|            cuda_sys::cuDeviceGet(device.as_mut_ptr(), ordinal as i32)
102|                .result()
103|                .map_err(|_| CudaError::DeviceUnavailable { ordinal })?;
104|            device.assume_init()
105|        };
106|
107|        // Get device name
108|        let mut name_buf = [0i8; 256];
109|        unsafe {
110|            cuda_sys::cuDeviceGetName(name_buf.as_mut_ptr(), name_buf.len() as i32, cu_device)
111|        };
112|        let name: String = name_buf
113|            .iter()
114|            .take_while(|&&c| c != 0)
115|            .map(|&c| c as u8)
116|            .collect::<Vec<u8>>()
117|            .into_iter()
118|            .map(|b| b as char)
119|            .collect();
120|
121|        // Get compute capability
122|        let mut major = std::mem::MaybeUninit::uninit();
123|        let mut minor = std::mem::MaybeUninit::uninit();
124|        unsafe {
125|            cuda_sys::cuDeviceGetAttribute(
126|                major.as_mut_ptr(),
127|                cuda_sys::CUdevice_attribute_enum_CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR,
128|                cu_device,
129|            )
130|            .result()
131|            .map_err(|_| CudaError::DeviceUnavailable { ordinal })?;
132|            cuda_sys::cuDeviceGetAttribute(
133|                minor.as_mut_ptr(),
134|                cuda_sys::CUdevice_attribute_enum_CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR,
135|                cu_device,
136|            )
137|            .result()
138|            .map_err(|_| CudaError::DeviceUnavailable { ordinal })?;
139|        }
140|        let (major, minor) = unsafe { (major.assume_init(), minor.assume_init()) };
141|
142|        // Get memory info
143|        let (free_memory, total_memory) = unsafe {
144|            let mut free: usize = 0;
145|            let mut total: usize = 0;
146|            cuda_sys::cuMemGetInfo_v2(&mut free, &mut total)
147|                .result()
148|                .map_err(|_| CudaError::DeviceUnavailable { ordinal })?;
149|            (free as u64, total as u64)
150|        };
151|
152|        let device_info = CudaDeviceInfo {
153|            ordinal,
154|            name: name.clone(),
155|            compute_capability: (major, minor),
156|            total_memory,
157|            free_memory,
158|        };
159|
160|        // Retain primary context
161|        let ctx =
162|            CudaContext::new(ordinal).map_err(|e| CudaError::ContextCreation(e.to_string()))?;
163|
164|        debug!(
165|            ordinal,
166|            name = %device_info.name,
167|            cc = "%d.%d", major, minor,
168|            "CUDA runtime: initialized device"
169|        );
170|
171|        Ok(Self {
172|            ctx,
173|            ordinal,
174|            device_info,
175|        })
176|    }
177|
178|    /// Create a CUDA runtime for the first available device (ordinal 0).
179|    pub fn for_default_device() -> Result<Self, CudaError> {
180|        Self::new(0)
181|    }
182|
183|    /// Returns the underlying cuda-oxide context.
184|    pub fn context(&self) -> &Arc<CudaContext> {
185|        &self.ctx
186|    }
187|
188|    /// Returns the device ordinal.
189|    pub fn ordinal(&self) -> usize {
190|        self.ordinal
191|    }
192|
193|    /// Returns cached device info.
194|    pub fn device_info(&self) -> &CudaDeviceInfo {
195|        &self.device_info
196|    }
197|
198|    /// Create a new non-blocking stream in this context.
199|    pub fn new_stream(&self) -> Result<Arc<cuda_core::CudaStream>, CudaError> {
200|        self.ctx
201|            .new_stream()
202|            .map_err(|e| CudaError::ContextCreation(e.to_string()))
203|    }
204|
205|    /// Synchronize the context (blocks until all pending work completes).
206|    pub fn synchronize(&self) -> Result<(), CudaError> {
207|        self.ctx
208|            .synchronize()
209|            .map_err(|e| CudaError::ContextCreation(e.to_string()))
210|    }
211|
212|    /// Check if this runtime is still valid (context not destroyed).
213|    pub fn is_valid(&self) -> bool {
214|        !self.ctx.cu_ctx().is_null()
215|    }
216|}
217|
218|/// Initialize CUDA and enumerate available devices.
219|///
220|/// Returns a list of `CudaDeviceInfo` for all devices that can be queried.
221|/// Returns an empty list if CUDA is not available or no devices are found.
222|pub fn enumerate_devices() -> Result<Vec<CudaDeviceInfo>, CudaError> {
223|    unsafe {
224|        cuda_core::init(0).map_err(|_| CudaError::NotAvailable)?;
225|    };
226|
227|    let mut device_count: i32 = 0;
228|    unsafe {
229|        cuda_sys::cuDeviceGetCount(&mut device_count)
230|            .result()
231|            .map_err(|_| CudaError::NotAvailable)?;
232|    };
233|
234|    if device_count == 0 {
235|        return Ok(Vec::new());
236|    }
237|
238|    let mut devices = Vec::with_capacity(device_count as usize);
239|
240|    for ordinal in 0..device_count {
241|        // Get device handle
242|        let cu_device = match unsafe {
243|            let mut device = std::mem::MaybeUninit::uninit();
244|            cuda_sys::cuDeviceGet(device.as_mut_ptr(), ordinal)
245|                .result()
246|                .map_err(|_| CudaError::DeviceUnavailable {
247|                    ordinal: ordinal as usize,
248|                })?;
249|            Ok::<i32, CudaError>(device.assume_init())
250|        } {
251|            Ok(d) => d,
252|            Err(e) => {
253|                warn!(ordinal, "CUDA device enumeration skipped: {e}");
254|                continue;
255|            }
256|        };
257|
258|        // Get device name
259|        let mut name_buf = [0i8; 256];
260|        unsafe {
261|            cuda_sys::cuDeviceGetName(name_buf.as_mut_ptr(), name_buf.len() as i32, cu_device)
262|        };
263|        let name: String = name_buf
264|            .iter()
265|            .take_while(|&&c| c != 0)
266|            .map(|&c| c as u8)
267|            .collect::<Vec<u8>>()
268|            .into_iter()
269|            .map(|b| b as char)
270|            .collect();
271|
272|        // Get compute capability
273|        let (major, minor) =
274|            {
275|                let mut m = std::mem::MaybeUninit::uninit();
276|                let mut n = std::mem::MaybeUninit::uninit();
277|                unsafe {
278|                    cuda_sys::cuDeviceGetAttribute(
279|                    m.as_mut_ptr(),
280|                    cuda_sys::CUdevice_attribute_enum_CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR,
281|                    cu_device,
282|                )
283|                .result()
284|                .map_err(|_| CudaError::DeviceUnavailable { ordinal: ordinal as usize })?;
285|                    cuda_sys::cuDeviceGetAttribute(
286|                    n.as_mut_ptr(),
287|                    cuda_sys::CUdevice_attribute_enum_CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR,
288|                    cu_device,
289|                )
290|                .result()
291|                .map_err(|_| CudaError::DeviceUnavailable { ordinal: ordinal as usize })?;
292|                    (m.assume_init(), n.assume_init())
293|                }
294|            };
295|
296|        // Get memory info
297|        let (free_memory, total_memory) = unsafe {
298|            let mut free: usize = 0;
299|            let mut total: usize = 0;
300|            cuda_sys::cuMemGetInfo_v2(&mut free, &mut total)
301|                .result()
302|                .map_err(|_| CudaError::DeviceUnavailable {
303|                    ordinal: ordinal as usize,
304|                })?;
305|            (free as u64, total as u64)
306|        };
307|
308|        let _device_info = CudaDeviceInfo {
309|            ordinal: ordinal as usize,
310|            name: name.clone(),
311|            compute_capability: (major, minor),
312|            total_memory,
313|            free_memory,
314|        };
315|
316|        devices.push(CudaDeviceInfo {
317|            ordinal: ordinal as usize,
318|            name,
319|            compute_capability: (major, minor),
320|            total_memory,
321|            free_memory,
322|        });
323|    }
324|
325|    Ok(devices)
326|}
327|
328|/// Select the best device for a model of the given size.
329|///
330|/// Prioritizes:
331|/// 1. Devices with enough free VRAM
332|/// 2. Higher compute capability (tcgen05 > WGMMA > CPU)
333|/// 3. More free memory as tiebreaker
334|pub fn select_best_device(model_bytes: u64) -> Option<CudaDeviceInfo> {
335|    let devices = enumerate_devices().unwrap_or_default();
336|
337|    let mut candidates: Vec<&CudaDeviceInfo> = devices
338|        .iter()
339|        .filter(|d| d.can_hold_model(model_bytes))
340|        .collect();
341|
342|    if candidates.is_empty() {
343|        return None;
344|    }
345|
346|    // Sort by: tcgen05 support > WGMMA support > free memory descending
347|    candidates.sort_by(|a, b| {
348|        let a_tc = if a.supports_tcgen05() { 3 } else { 0 };
349|        let a_wg = if a.supports_wgmma() { 2 } else { 0 };
350|        let b_tc = if b.supports_tcgen05() { 3 } else { 0 };
351|        let b_wg = if b.supports_wgmma() { 2 } else { 0 };
352|
353|        let a_score = a_tc + a_wg + (a.free_memory as i64 / (1024 * 1024 * 1024));
354|        let b_score = b_tc + b_wg + (b.free_memory as i64 / (1024 * 1024 * 1024));
355|
356|        b_score.cmp(&a_score)
357|    });
358|
359|    candidates.first().cloned().cloned()
360|}
361|
362|/// Check if CUDA is available on this system.
363|pub fn is_available() -> bool {
364|    enumerate_devices().is_ok() && !enumerate_devices().unwrap_or_default().is_empty()
365|}
