368|pub fn device_count() -> usize {
369|    let mut count: i32 = 0;
370|    match unsafe { cuda_sys::cuDeviceGetCount(&mut count).result() } {
371|        Ok(_) => count as usize,
372|        Err(_) => 0,
373|    }
374|}
