380|/// Allocate device memory.
381|///
382|/// Wraps `cuMemAlloc_v2` to provide a safe interface for GPU buffer allocation.
383|pub fn allocate_device_memory(size_in_bytes: usize) -> Result<*mut u8, CudaError> {
384|    let mut dptr: u64 = 0;
385|    unsafe {
386|        cuda_sys::cuMemAlloc_v2(&mut dptr, size_in_bytes)
387|            .result()
388|            .map_err(|e| CudaError::DriverError(format!("{:?}", e)))?;
389|        Ok(dptr as *mut u8)
390|    }
391|}
