393|/// Free device memory.
394|///
395|/// Wraps `cuMemFree_v2` to release previously allocated GPU buffers.
396|pub fn free_device_memory(ptr: *mut u8) -> Result<(), CudaError> {
397|    unsafe {
398|        cuda_sys::cuMemFree_v2(ptr as u64)
399|            .result()
400|            .map_err(|e| CudaError::DriverError(format!("{:?}", e)))?;
401|        Ok(())
